            if cols and cols == list(range(cols[0], cols[-1] + 1)):
                key = (r, r + 3)
                colors = [grid[r][c] for c in cols]
                break
    if key is None:
        return out
    kr0, kr1 = key
    for r in range(kr0, kr1):
        out[r] = [0] * w

    # The shape can contain diagonally touching sections, so group all cells
    # by color rather than relying on connected components.
    by_color = {}
    for r in range(h):
